		invArray[n] = IntMath.pow((int) factArray[n], MOD - 2, MOD);
		for (int i = n; i > 0; --i) invArray[i - 1] = invArray[i] * i % MOD;
		BiFunction<Integer, Integer, Long> combination = (i, j) -> factArray[i] * invArray[j] % MOD * invArray[i - j] % MOD;
		if (k == 0) {
			writer.println(factArray[n]);
		} else if (k > n) {
