				totalCount += ((remaining - i) & 1) != 0 ? -temp : temp;
			}
			totalCount = (totalCount % MOD + MOD) % MOD;
			totalCount = totalCount * 2 * combination.apply(n, kVal) % MOD;
			writer.println(totalCount);
		}
	}

	static class FastScanner {
		private final java.io.InputStream inStream = System.in;
		private final byte[] buf = new byte[1024];
		private int ptr = 0;
		private int buflen = 0;
		private boolean hasNextByte() {
			if (ptr < buflen) return true;
			ptr = 0;
			try {
				buflen = inStream.read(buf);
			} catch (java.io.IOException e) {
				e.printStackTrace();
			}
			return buflen > 0;
		}
		private byte readByte() {
			return hasNextByte() ? buf[ptr++] : -1;
		}
		private static boolean isPrintable(byte c) {
			return c > 32 || c < 0;
		}
		private static boolean isNumber(int c) {
			return '0' <= c && c <= '9';
		}
		public boolean hasNext() {
