def process_input_data():
    input_data = sys.stdin.read().strip().split()
    n = int(input_data[0])
    k = int(input_data[1])
    MOD = 998244353

    fact_array = [1] * (n + 1)
    inv_array = [1] * (n + 1)

    for i in range(n):
        fact_array[i + 1] = fact_array[i] * (i + 1) % MOD

    inv_array[n] = pow(fact_array[n], MOD - 2, MOD)
    for i in range(n, 0, -1):
        inv_array[i - 1] = inv_array[i] * i % MOD

    def combination(i, j):
        return fact_array[i] * inv_array[j] % MOD * inv_array[i - j] % MOD

    def pow_mod(base, exp):
        return pow(base, exp, MOD)

    if k == 0:
        print(fact_array[n])
    elif k > n:
        print(0)
    else:
        kVal = k
        remaining = n - kVal
        totalCount = 0
        for i in range(1, remaining + 1):
            temp = combination(remaining, i) * pow_mod(i, n) % MOD
            if (remaining - i) % 2 != 0:
                totalCount -= temp
            else:
                totalCount += temp
        totalCount %= MOD
        totalCount = totalCount * 2 * combination(n, kVal) % MOD
        print(totalCount)

if __name__ == "__main__":
    main()

